// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.benchmark;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;

import org.eclipse.rdf4j.sail.lmdb.evaluation.select.DecisionRecorder.RecordedDecision;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/** Portability may erase numeric tag parameters, but must not erase an admitted strategy's semantic identity. */
class LmdbNativeGoldenNormalizationContractTest {

	@ParameterizedTest
	@ValueSource(strings = { "packedFtree", "packedFtreeAggregate" })
	void serialAndParallelVariantsKeepTheirIdentities(String family) {
		assertThat(LmdbNativeGoldenDecisionsTest.normalize(family + "(serial)"))
				.isEqualTo(family + "(serial)");
		assertThat(LmdbNativeGoldenDecisionsTest.normalize(family + "(parallel)"))
				.isEqualTo(family + "(parallel)");
	}

	@ParameterizedTest
	@ValueSource(strings = { "packedFtree(parallel,workers=4)", "packedFtree(parallel:workers=4)",
			"packedFtree(parallel:workers=16,partitions=64)" })
	void numericWorkerParametersAreRemovedWithoutLosingTheParallelVariant(String tag) {
		assertThat(LmdbNativeGoldenDecisionsTest.normalize(tag)).isEqualTo("packedFtree(parallel)");
	}

	@Test
	void numericOnlyMachineParametersRemainPortable() {
		assertThat(LmdbNativeGoldenDecisionsTest.normalize("parallelAggregation(workers=4,rangePartitioned=16)"))
				.isEqualTo("parallelAggregation");
		assertThat(LmdbNativeGoldenDecisionsTest.normalize("parallelAggregation(workers=32,rangePartitioned=128)"))
				.isEqualTo("parallelAggregation");
	}

	@Test
	void executedPackedRoutesKeepTheSameSemanticDistinction() {
		assertThat(LmdbNativeGoldenDecisionsTest.normalizeExecuted("packedFtree(parallel:workers=4)"))
				.isEqualTo("packedFtree(parallel)");
		assertThat(LmdbNativeGoldenDecisionsTest.normalizeExecuted("packedFtree(serial)"))
				.isEqualTo("packedFtree(serial)");
	}

	@Test
	void executedKernelTierNormalizationRetainsItsExistingContract() {
		assertThat(LmdbNativeGoldenDecisionsTest.normalizeExecuted("irAggregateParallelInterpreted(workers=4)"))
				.isEqualTo("irAggregateParallel");
	}

	@Test
	void aGoldenInventoryCanTellWhichPackedVariantWasAdmitted() {
		String serialOnly = fixture(List.of("nestedLoop", "packedFtree(serial)"));
		String parallelOnly = fixture(List.of("nestedLoop", "packedFtree(parallel)"));
		String both = fixture(List.of("nestedLoop", "packedFtree(serial)", "packedFtree(parallel)"));

		assertThat(LmdbNativeGoldenDecisionsTest.normalize(serialOnly))
				.isNotEqualTo(LmdbNativeGoldenDecisionsTest.normalize(parallelOnly));
		assertThat(LmdbNativeGoldenDecisionsTest.normalize(both))
				.contains("nestedLoop,packedFtree(serial),packedFtree(parallel)");
	}

	@Test
	void nonnumericPhysicalLabelsAreNotMistakenForMachineSizes() {
		assertThat(LmdbNativeGoldenDecisionsTest.normalize("factorizedTail(prefix=chunkPipeline,branches=3)"))
				.isEqualTo("factorizedTail(prefix=chunkPipeline)");
	}

	private static String fixture(List<String> admitted) {
		return new RecordedDecision("Projection", "row/join dispatch", "normal", "nestedLoop", null,
				"smallest quote", admitted, List.of()).fixtureLine();
	}
}
